-- Realistic additional test questions over artist biographies, v3 (2026-10-13): any column; most need columns the initial build does not read.
-- QX1: For painters, sculptors, photographers, printmakers and others: how many were born in Europe and how many in North America?
SELECT CASE WHEN field LIKE '%Painting%' THEN 'Painting' WHEN field LIKE '%Sculpture%' THEN 'Sculpture' WHEN field LIKE '%Photography%' THEN 'Photography' WHEN field LIKE '%Printmaking%' THEN 'Printmaking' ELSE 'Other' END AS main_field, COUNT(*) AS artists, SUM(CASE WHEN birth_continent = 'Europe' THEN 1 ELSE 0 END) AS born_in_europe, SUM(CASE WHEN birth_continent = 'North America' THEN 1 ELSE 0 END) AS born_in_north_america FROM art GROUP BY main_field;
-- QX2: For the ten cities where the most artists died: how many died there, and how many of them were also born there?
SELECT death_city, COUNT(*) AS artists, SUM(CASE WHEN birth_city = death_city THEN 1 ELSE 0 END) AS born_there_too FROM art WHERE death_city IS NOT NULL AND death_city <> '' GROUP BY death_city ORDER BY artists DESC, death_city LIMIT 10;
-- QX3: Among artists with a known age, did those born in the 1700s, 1800s and 1900s differ in how long they lived and how often they taught?
SELECT CASE WHEN birth_date LIKE '17%' THEN '1700s' WHEN birth_date LIKE '18%' THEN '1800s' ELSE '1900s' END AS birth_century, COUNT(*) AS artists, AVG(age) AS average_age, AVG(teaching) AS share_who_taught FROM art WHERE (birth_date LIKE '17%' OR birth_date LIKE '18%' OR birth_date LIKE '19%') AND age IS NOT NULL AND age <> '' GROUP BY birth_century;
-- QX4: For artists whose images show people, geometric shapes, nature, buildings or other things: how many, and how many awards on average?
SELECT CASE WHEN object LIKE '%Human%' OR object LIKE '%Person%' OR object LIKE '%People%' OR object LIKE '%Figure%' OR object LIKE '%Woman%' THEN 'People' WHEN object LIKE '%Geometric%' OR object LIKE '%Shape%' THEN 'Geometric shapes' WHEN object LIKE '%Tree%' OR object LIKE '%Mountain%' OR object LIKE '%Sky%' OR object LIKE '%Water%' OR object LIKE '%Sea%' THEN 'Nature' WHEN object LIKE '%Building%' OR object LIKE '%City%' OR object LIKE '%Architecture%' THEN 'Buildings' ELSE 'Other' END AS subject_group, COUNT(*) AS artists, AVG(awards) AS average_awards FROM art WHERE object IS NOT NULL AND object <> '' GROUP BY subject_group;
-- QX5: For balanced, asymmetrical, centralized, dynamic and other compositions: how many artists, what share taught, and how many awards in total?
SELECT CASE WHEN composition LIKE '%Balanced%' THEN 'Balanced' WHEN composition LIKE '%Asymmetr%' THEN 'Asymmetrical' WHEN composition LIKE '%Centr%' THEN 'Centralized' WHEN composition LIKE '%Dynamic%' THEN 'Dynamic' ELSE 'Other' END AS composition_group, COUNT(*) AS artists, AVG(teaching) AS share_who_taught, SUM(awards) AS total_awards FROM art WHERE composition IS NOT NULL AND composition <> '' GROUP BY composition_group;
-- QX6: Which five nationalities won the most awards in total, and how many of their artists won at least one?
SELECT nationality, SUM(awards) AS total_awards, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE nationality IS NOT NULL AND nationality <> '' AND nationality NOT LIKE '%||%' GROUP BY nationality ORDER BY total_awards DESC, nationality LIMIT 5;
-- QX7: How many artists died in the 1800s, the 1900s, the 2000s, or have no recorded death, and how many awards did each group win on average?
SELECT CASE WHEN death_date LIKE '18%' THEN 'died 1800s' WHEN death_date LIKE '19%' THEN 'died 1900s' WHEN death_date LIKE '20%' THEN 'died 2000s' ELSE 'no recorded death' END AS death_period, COUNT(*) AS artists, AVG(awards) AS average_awards FROM art GROUP BY death_period;
-- QX8: Which birth cities produced at least eight artists, and how many of those artists won an award?
SELECT birth_city, COUNT(*) AS artists, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE birth_city IS NOT NULL AND birth_city <> '' AND birth_city NOT LIKE '%||%' GROUP BY birth_city HAVING COUNT(*) >= 8;
-- QX9: For American, French, British, German, Italian and Japanese artists, how many awards did teachers and non-teachers win on average?
SELECT nationality, teaching, COUNT(*) AS artists, AVG(awards) AS average_awards FROM art WHERE nationality IN ('American', 'French', 'British', 'German', 'Italian', 'Japanese') GROUP BY nationality, teaching;
-- QX10: For painters, sculptors, photographers and others, how many lived longer than the average artist?
SELECT CASE WHEN field LIKE '%Painting%' THEN 'Painting' WHEN field LIKE '%Sculpture%' THEN 'Sculpture' WHEN field LIKE '%Photography%' THEN 'Photography' ELSE 'Other' END AS main_field, COUNT(*) AS artists FROM art WHERE age IS NOT NULL AND age <> '' AND CAST(age AS INTEGER) > (SELECT AVG(CAST(age AS INTEGER)) FROM art WHERE age IS NOT NULL AND age <> '') GROUP BY main_field;
-- QX11: For artists affiliated with an academy, a school or college, or something else: how many, how many awards in total, and how many won at least one?
SELECT CASE WHEN art_institution LIKE '%Academ%' OR art_institution LIKE '%Akadem%' THEN 'Academy' WHEN art_institution LIKE '%School%' OR art_institution LIKE '%College%' OR art_institution LIKE '%Schule%' THEN 'School or college' ELSE 'Other' END AS institution_group, COUNT(*) AS artists, SUM(awards) AS total_awards, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE art_institution IS NOT NULL AND art_institution <> '' GROUP BY institution_group;
-- QX12: How many awards did artists active only in the 20th century win in total?
SELECT SUM(awards) AS total_awards FROM art WHERE century = '20th';
